def apply(asset, save=False, hou=None):
    if save:
        raise RuntimeError("Use VerifyFull to persist this patch")
    if asset.path() != '/obj/StreetBuilding_DEV' or asset.type().name() != 'pcgbike::StreetBuilding::1.0':
        raise RuntimeError('Unexpected Live asset')
    if asset.parm('parapet_enabled') is not None and 'STREETBUILDING_ROOF_TRIM_20260911' in asset.node('StreetBuildingCore/PARSE_GENERATION_RULES').parm('snippet').eval():
        return {'status':'UNCHANGED'}
    originals={}
    changed={}
    for name, operations in OPERATIONS.items():
        parm=asset.node('StreetBuildingCore/'+name).parm('snippet')
        code=parm.eval()
        if hashlib.sha256(code.encode()).hexdigest()!=HASHES[name]:
            raise RuntimeError('Live precondition mismatch: '+name)
        originals[name]=code
        for old,new in operations:
            if old not in code: raise RuntimeError('Missing exact precondition: '+name)
            code=code.replace(old,new)
        changed[name]=code
    group=asset.parmTemplateGroup()
    try:
        updated=asset.parmTemplateGroup()
        updated.insertBefore('parapet_height',hou.ToggleParmTemplate('parapet_enabled','生成女儿墙 / Generate Parapet',default_value=True))
        height=hou.FloatParmTemplate('parapet_height','女儿墙高度 / Parapet Height (m)',1,default_value=(.6,),min=0,max=3,min_is_strict=True,max_is_strict=True,naming_scheme=hou.parmNamingScheme.Base1)
        height.setHelp(updated.find('parapet_height').help())
        updated.replace('parapet_height',height)
        asset.setParmTemplateGroup(updated)
        for name,code in changed.items(): asset.node('StreetBuildingCore/'+name).parm('snippet').set(code)
        return {'status':'APPLIED','nodes':list(changed),'saved':False}
    except Exception:
        for name,code in originals.items(): asset.node('StreetBuildingCore/'+name).parm('snippet').set(code)
        asset.setParmTemplateGroup(group)
        raise
